import{_ as r,a0 as d,w as p,s as l,I as e,x as s,a1 as i,A as o,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"走進Linux之systemd啓動過程 | LCTT x X-CMD","titleTemplate":false,"description":"走進Linux之systemd啓動過程 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"走進Linux之systemd啓動過程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"走進Linux之systemd啓動過程 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150316 Systemd Boot Process a Close Look in Linux","title":"走進Linux之systemd啓動過程","tag":"201505","desc":""},"relativePath":"201505/20150316 Systemd Boot Process a Close Look in Linux.md","filePath":"[post].md"}'),m={name:"201505/20150316 Systemd Boot Process a Close Look in Linux.md"};function u(g,t,y,b,x,L){const n=d("Link");return p(),l("div",null,[t[19]||(t[19]=e("h1",{id:"走進linux之systemd啓動過程",tabindex:"-1"},[s("走進Linux之systemd啓動過程 "),e("a",{class:"header-anchor",href:"#走進linux之systemd啓動過程","aria-label":"Permalink to “走進Linux之systemd啓動過程”"},"​")],-1)),e("p",null,[t[1]||(t[1]=s("Linux系統的啓動方式有點複雜，而且總是有需要優化的地方。傳統的Linux系統啓動過程主要由著名的init進程（也被稱為SysV init啓動系統）處理，而基於init的啓動系統被認為有效率不足的問題，systemd是Linux系統機器的另一種啓動方式，宣稱彌補了以",-1)),i(n,{href:"http://0pointer.de/blog/projects/self-documented-boot.html"},{default:o(()=>[...t[0]||(t[0]=[s("傳統Linux SysV init",-1)])]),_:1}),t[2]||(t[2]=s("為基礎的系統的缺點。在這裏我們將着重討論systemd的特性和爭議，但是為了更好地理解它，也會看一下通過傳統的以SysV init為基礎的系統的Linux啓動過程是什麼樣的。友情提醒一下，systemd仍然處在測試階段，而未來發布的Linux操作系統也正準備用systemd啓動管理程序替代當前的啓動過程（LCTT 譯註：截止到本文發表，主流的Linux發行版已經有很多采用了 systemd）。",-1))]),t[20]||(t[20]=e("h3",{id:"理解linux啓動過程",tabindex:"-1"},[s("理解Linux啓動過程 "),e("a",{class:"header-anchor",href:"#理解linux啓動過程","aria-label":"Permalink to “理解Linux啓動過程”"},"​")],-1)),t[21]||(t[21]=e("p",null,"在我們打開Linux電腦的電源後第一個啓動的進程就是init。分配給init進程的PID是1。它是系統其他所有進程的父進程。當一台Linux電腦啓動後，處理器會先在系統存儲中查找BIOS，之後BIOS會檢測系統資源然後找到第一個引導設備，通常為硬盤，然後會查找硬盤的主引導記錄（MBR），然後加載到內存中並把控制權交給它，以後的啓動過程就由MBR控制。",-1)),t[22]||(t[22]=e("p",null,"主引導記錄會初始化引導程序（Linux上有兩個著名的引導程序，GRUB和LILO，80%的Linux系統在用GRUB引導程序），這個時候GRUB或LILO會加載內核模組。內核會馬上查找/sbin下的“init”程序並執行它。從這裏開始init成為了Linux系統的父進程。init讀取的第一個文件是/etc/inittab，通過它init會確定我們Linux操作系統的運行級別。它會從文件/etc/fstab裏查找分區表信息然後做相應的掛載。然後init會啓動/etc/init.d裏指定的默認啓動級別的所有服務/腳本。所有服務在這裏通過init一個一個被初始化。在這個過程裏，init每次只啓動一個服務，所有服務/守護進程都在後台執行並由init來管理。",-1)),t[23]||(t[23]=e("p",null,"關機過程差不多是相反的過程，首先init停止所有服務，最後階段會卸載文件系統。",-1)),t[24]||(t[24]=e("p",null,"以上提到的啓動過程有一些不足的地方。而用一種更好的方式來替代傳統init的需求已經存在很長時間了。也產生了許多替代方案。其中比較著名的有Upstart，Epoch，Muda和Systemd。而Systemd獲得最多關注並被認為是目前最佳的方案。",-1)),t[25]||(t[25]=e("h3",{id:"理解systemd",tabindex:"-1"},[s("理解Systemd "),e("a",{class:"header-anchor",href:"#理解systemd","aria-label":"Permalink to “理解Systemd”"},"​")],-1)),t[26]||(t[26]=e("p",null,"開發Systemd的主要目的就是減少系統引導時間和計算開銷。Systemd（系統管理守護進程），最開始以GNU GPL協議授權開發，現在已轉為使用GNU LGPL協議，它是如今討論最熱烈的引導和服務管理程序。如果你的Linux系統配置為使用Systemd引導程序，它取替傳統的SysV init，啓動過程將交給systemd處理。Systemd的一個核心功能是它同時支持SysV init的後開機啓動腳本。",-1)),e("p",null,[t[4]||(t[4]=s("Systemd引入了並行啓動的概念，它會為每個需要啓動的守護進程建立一個套接字，這些套接字對於使用它們的進程來説是抽象的，這樣它們可以允許不同守護進程之間進行交互。Systemd會創建新進程併為每個進程分配一個控制組（cgroup）。處於不同控制組的進程之間可以通過內核來互相通信。",-1)),i(n,{href:"http://0pointer.de/blog/projects/self-documented-boot.html"},{default:o(()=>[...t[3]||(t[3]=[s("systemd處理開機啓動進程",-1)])]),_:1}),t[5]||(t[5]=s("的方式非常漂亮，和傳統基於init的系統比起來優化了太多。讓我們看下Systemd的一些核心功能。",-1))]),t[27]||(t[27]=a(`<ul><li>和init比起來引導過程簡化了很多</li><li>Systemd支持併發引導過程從而可以更快啓動</li><li>通過控制組來追蹤進程，而不是PID</li><li>優化了處理引導過程和服務之間依賴的方式</li><li>支持系統快照和恢復</li><li>監控已啓動的服務；也支持重啓已崩潰服務</li><li>包含了systemd-login模組用於控制用户登錄</li><li>支持加載和卸載組件</li><li>低內存使用痕跡以及任務調度能力</li><li>記錄事件的Journald模組和記錄系統日誌的syslogd模組</li></ul><p>Systemd同時也清晰地處理了系統關機過程。它在/usr/lib/systemd/目錄下有三個腳本，分別叫systemd-halt.service，systemd-poweroff.service，systemd-reboot.service。這幾個腳本會在用户選擇關機，重啓或待機時執行。在接收到關機事件時，systemd首先卸載所有文件系統並停止所有內存交換設備，斷開存儲設備，之後停止所有剩下的進程。</p><p><img src="http://images.linoxide.com/systemd-boot-process.jpg" alt=""></p><h3 id="systemd結構概覽" tabindex="-1">Systemd結構概覽 <a class="header-anchor" href="#systemd結構概覽" aria-label="Permalink to “Systemd結構概覽”">​</a></h3><p>讓我們看一下Linux系統在使用systemd作為引導程序時的開機啓動過程的結構性細節。為了簡單，我們將在下面按步驟列出來這個過程：</p><p><strong>1.</strong> 當你打開電源後電腦所做的第一件事情就是BIOS初始化。BIOS會讀取引導設備設定，定位並傳遞系統控制權給MBR（假設硬盤是第一引導設備）。</p><p><strong>2.</strong> MBR從Grub或LILO引導程序讀取相關信息並初始化內核。接下來將由Grub或LILO繼續引導系統。如果你在grub配置文件裏指定了systemd作為引導管理程序，之後的引導過程將由systemd完成。Systemd使用“target”來處理引導和服務管理過程。這些systemd裏的“target”文件被用於分組不同的引導單元以及啓動同步進程。</p><p><strong>3.</strong> systemd執行的第一個目標是<strong>default.target</strong>。但實際上default.target是指向<strong>graphical.target</strong>的軟鏈接。Linux裏的軟鏈接用起來和Windows下的快捷方式一樣。文件Graphical.target的實際位置是/usr/lib/systemd/system/graphical.target。在下面的截圖裏顯示了graphical.target文件的內容。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/graphical1.png" alt=""></p><p><strong>4.</strong> 在這個階段，會啓動<strong>multi-user.target</strong>而這個target將自己的子單元放在目錄“/etc/systemd/system/multi-user.target.wants”裏。這個target為多用户支持設定系統環境。非root用户會在這個階段的引導過程中啓用。防火牆相關的服務也會在這個階段啓動。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/multi-user-target1.png" alt=""></p><p>&quot;multi-user.target&quot;會將控制權交給另一層“<strong>basic.target</strong>”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Basic-Target.png" alt=""></p><p><strong>5.</strong> &quot;basic.target&quot;單元用於啓動普通服務特別是圖形管理服務。它通過/etc/systemd/system/basic.target.wants目錄來決定哪些服務會被啓動，basic.target之後將控制權交給<strong>sysinit.target</strong>.</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Sysint-Target.png" alt=""></p><p><strong>6.</strong> &quot;sysinit.target&quot;會啓動重要的系統服務例如系統掛載，內存交換空間和設備，內核補充選項等等。sysinit.target在啓動過程中會傳遞給<strong>local-fs.target</strong>。這個target單元的內容如下面截圖裏所展示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/local-FS-Target.png" alt=""></p><p><strong>7.</strong> local-fs.target，這個target單元不會啓動用户相關的服務，它只處理底層核心服務。這個target會根據/etc/fstab和/etc/inittab來執行相關操作。</p><h3 id="系統引導性能分析" tabindex="-1">系統引導性能分析 <a class="header-anchor" href="#系統引導性能分析" aria-label="Permalink to “系統引導性能分析”">​</a></h3><p>Systemd提供了工具用於識別和定位引導相關的問題或性能影響。<strong>Systemd-analyze</strong>是一個內建的命令，可以用來檢測引導過程。你可以找出在啓動過程中出錯的單元，然後跟蹤並改正引導組件的問題。在下面列出一些常用的systemd-analyze命令。</p><p><strong>systemd-analyze time</strong> 用於顯示內核和普通用户空間啓動時所花的時間。</p><pre><code>$ systemd-analyze time

Startup finished in 1440ms (kernel) + 3444ms (userspace)
</code></pre><p><strong>systemd-analyze blame</strong> 會列出所有正在運行的單元，按從初始化開始到當前所花的時間排序，通過這種方式你就知道哪些服務在引導過程中要花較長時間來啓動。</p><pre><code>$ systemd-analyze blame

2001ms mysqld.service
234ms httpd.service
191ms vmms.service
</code></pre><p><strong>systemd-analyze verify</strong> 顯示在所有系統單元中是否有語法錯誤。</p><p><strong>systemd-analyze plot</strong> 可以用來把整個引導過程寫入一個SVG格式文件裏。整個引導過程非常長不方便閲讀，所以通過這個命令我們可以把輸出寫入一個文件，之後再查看和分析。下面這個命令就是做這個。</p><pre><code>systemd-analyze plot &gt; boot.svg
</code></pre><h3 id="systemd的爭議" tabindex="-1">Systemd的爭議 <a class="header-anchor" href="#systemd的爭議" aria-label="Permalink to “Systemd的爭議”">​</a></h3><p>Systemd並沒有幸運地獲得所有人的青睞，一些專家和管理員對於它的工作方式和開發有不同意見。根據對於Systemd的批評，它不是“類Unix”方式因為它試着替換一些系統服務。一些專家也不喜歡使用二進制配置文件的想法。據説編輯systemd配置非常困難而且沒有一個可用的圖形工具。</p><h3 id="如何在ubuntu-14-04和12-04上測試systemd" tabindex="-1">如何在Ubuntu 14.04和12.04上測試Systemd <a class="header-anchor" href="#如何在ubuntu-14-04和12-04上測試systemd" aria-label="Permalink to “如何在Ubuntu 14.04和12.04上測試Systemd”">​</a></h3><p>本來，Ubuntu決定從Ubuntu 16.04 LTS開始使用Systemd來替換當前的引導過程。Ubuntu 16.04預計在2016年4月發佈，但是考慮到Systemd的流行和需求，剛剛發佈的<strong>Ubuntu 15.04</strong>採用它作為默認引導程序。另外，Ubuntu 14.04 Trusty Tahr和Ubuntu 12.04 Precise Pangolin的用户可以在他們的機器上測試Systemd。測試過程並不複雜，你所要做的只是把相關的PPA包含到系統中，更新倉庫並升級系統。</p><p><strong>聲明</strong>：請注意它仍然處於Ubuntu的測試和開發階段。升級測試包可能會帶來一些未知錯誤，最壞的情況下有可能損壞你的系統配置。請確保在嘗試升級前已經備份好重要數據。</p><p>在終端裏運行下面的命令來添加PPA到你的Ubuntu系統裏：</p><pre><code>sudo add-apt-repository ppa:pitti/systemd
</code></pre><p>你將會看到警告信息因為我們嘗試使用臨時/測試PPA，而它們是不建議用於實際工作機器上的。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/PPA-Systemd1.png" alt=""></p><p>然後運行下面的命令更新APT包管理倉庫。</p><pre><code>sudo apt-get update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Update-APT1.png" alt=""></p><p>運行下面的命令升級系統。</p><pre><code>sudo apt-get dist-upgrade
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/System-Upgrade.png" alt=""></p><p>就這些，你應該已經可以在你的Ubuntu系統裏看到Systemd配置文件了，打開/lib/systemd/目錄可以看到這些文件。</p><p>好吧，現在讓我們編輯一下grub配置文件指定systemd作為默認引導程序。可以使用Gedit文字編輯器編輯grub配置文件。</p><pre><code>sudo gedit /etc/default/grub
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Edit-Grub.png" alt=""></p><p>在文件裏修改GRUB_CMDLINE_LINUX_DEFAULT項，設定它的參數為：“<strong>init=/lib/systemd/systemd</strong>”</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Grub-Systemd.png" alt=""></p><p>就這樣，你的Ubuntu系統已經不再使用傳統的引導程序了，改為使用Systemd管理器。重啓你的機器然後查看systemd引導過程吧。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Sytemd-Boot.png" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>Systemd毫無疑問為改進Linux引導過程前進了一大步；它包含了一套漂亮的庫和守護進程配合工作來優化系統引導和關閉過程。許多Linux發行版正準備將它作為自己的正式引導程序。在以後的Linux發行版中，我們將有望看到systemd開機。但是另一方面，為了獲得成功並廣泛應用，systemd仍需要認真處理批評意見。</p><hr>`,53)),e("p",null,[t[7]||(t[7]=s("via: ",-1)),i(n,{href:"http://linoxide.com/linux-how-to/systemd-boot-process/"},{default:o(()=>[...t[6]||(t[6]=[s("http://linoxide.com/linux-how-to/systemd-boot-process/",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=s("作者：",-1)),i(n,{href:"http://linoxide.com/author/arunrz/"},{default:o(()=>[...t[8]||(t[8]=[s("Aun Raza",-1)])]),_:1}),t[12]||(t[12]=s(" 譯者：",-1)),i(n,{href:"https://github.com/zpl1025"},{default:o(()=>[...t[9]||(t[9]=[s("zpl1025",-1)])]),_:1}),t[13]||(t[13]=s(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[10]||(t[10]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=s("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[s("LCTT",-1)])]),_:1}),t[17]||(t[17]=s(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[s("Linux中國",-1)])]),_:1}),t[18]||(t[18]=s(" 榮譽推出",-1))])])}const T=r(m,[["render",u]]);export{h as __pageData,T as default};
